// Generate an arbitrary finite float and call Math_AbsF
float x = *FUZZ_PARAM(float);
// Invoke function under test
float r = Math_AbsF(x);
// No hard assertions about NaN handling per spec; just exercise the call
(void)r; // prevent unused warning

// Ensure x >= 0 to satisfy real-valued sqrt precondition
float x = *FUZZ_PARAM(float);
if (x < 0.0f) x = -x;
float r = Math_SqrtF(x);
(void)r;

// Safe division over all finite inputs
float a = *FUZZ_PARAM(float);
float b = *FUZZ_PARAM(float);
float r = Math_SafeDiv(a, b);
// Validate sentinel behavior when denominator near zero
float ab = b < 0.0f ? -b : b;
if (ab < 1.0e-6f) {
    // Expect sentinel 1e9
    FUZZ_ASSERT(r == 1.0e9f, "Math_SafeDiv should return sentinel when |b| < 1e-6");
}
(void)r;
